#include "ksPartRefreshTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
int main(){using T=ks::PartRefreshTask;using S=T::Stage;using C=T::Child;unsigned cases=0;for(unsigned current=0;current<256;++current)for(unsigned base=0;base<256;++base)for(unsigned mask=0;mask<16;++mask){T t;unsigned index=0,status=0,clears=0,globals=0;std::vector<unsigned>writes;while(t.stage()!=S::Complete){auto child=t.child();if(child!=C::None){if(index>=4||t.index()!=index||t.address()!=0x8041+index)throw std::runtime_error("loop binding");if(child==C::Status){status=(mask>>index)&1?3:0;if(!t.resumeChild(uint8_t(status)))throw std::runtime_error("status resume");}else if(child==C::Clear){++clears;t.resumeChild();}else{if(!status||t.part()!=uint8_t(index+base))throw std::runtime_error("global part");++globals;t.resumeChild();}continue;}auto stage=t.stage();auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](T::Read){return 0;},[](uint8_t){}))throw std::runtime_error("early");t.advanceBefore(cost,[&](T::Read r){return r==T::Read::Current?current:base;},[&](uint8_t v){writes.push_back(v);});if(stage==S::NextIndex)++index;}std::vector<unsigned>expected;unsigned active=0;for(unsigned i=0;i<4;++i)if(mask&(1<<i)){expected.push_back(uint8_t(i+base));++active;}expected.push_back(current);if(index!=4||clears!=active||globals!=active||writes!=expected)throw std::runtime_error("loop/result/order");++cases;}std::cout<<"PASS: "<<cases<<" pure part-refresh properties\n";}
